1	-- T4: money functions (R19-R30, R34, R35). Every money write is one plpgsql function in schema
2	-- private, called by server code through Prisma as the owner (D8). None is reachable through
3	-- PostgREST: private is not an exposed schema and execute is revoked from public/anon/authenticated.
4	-- Errors use fixed SQLSTATEs (P0400 validation, P0404 not found, P0409 conflict, P0422 business
5	-- rule); the message becomes the API body { "error": message }, so it never names another org's data.
6	
7	-- ---------------------------------------------------------------------------------------------
8	-- allocate_payment: fill the lease's unpaid invoices with this payment (R26). Caller holds the
9	-- lease lock (D7), so the unpaid amounts read here cannot change underneath us.
10	-- ---------------------------------------------------------------------------------------------
11	create or replace function private.allocate_payment(p_payment_id uuid)
12	returns void
13	language plpgsql
14	security invoker
15	set search_path = ''
16	as $$
17	#variable_conflict use_column
18	declare
19	  v_pay record;
20	  v_remaining bigint;
21	  v_inv record;
22	  v_take bigint;
23	begin
24	  select p.id, p.org_id, p.lease_id, p.amount_sen, p.unapplied_sen, p.status
25	    into v_pay
26	    from public.payments p
27	   where p.id = p_payment_id;
28	  if not found then
29	    raise exception using errcode = 'P0404', message = 'Payment not found';
30	  end if;
31	  if v_pay.status <> 'approved' then
32	    raise exception using errcode = 'P0409', message = 'Payment is not approved';
33	  end if;
34	
35	  -- R28: only the not-yet-allocated part is distributed, so a second call allocates nothing
36	  -- (a payment approved twice is allocated once, even if a caller slipped past the status check).
37	  select v_pay.amount_sen - coalesce(sum(a.amount_sen), 0)
38	    into v_remaining
39	    from public.payment_allocations a
40	   where a.payment_id = p_payment_id;
41	
42	  if v_remaining <= 0 then
43	    return;
44	  end if;
45	
46	  -- R26: due date, then deposit before rent (false sorts first), then period index; id breaks ties
47	  -- deterministically. Not-yet-due invoices are included (advance payments).
48	  for v_inv in
49	    select i.id,
50	           i.amount_sen - coalesce((select sum(a.amount_sen)
51	                                      from public.payment_allocations a
52	                                     where a.invoice_id = i.id), 0) as unpaid
53	      from public.invoices i
54	     where i.lease_id = v_pay.lease_id
55	     order by i.due_date, (i.kind = 'rent'), i.period_index nulls first, i.id
56	  loop
57	    exit when v_remaining <= 0;
58	    -- R46: skips fully paid invoices and 0-sen rent invoices, so no allocation row is ever 0 sen.
59	    continue when v_inv.unpaid <= 0;
60	    v_take := least(v_inv.unpaid, v_remaining);
61	    insert into public.payment_allocations (org_id, lease_id, payment_id, invoice_id, amount_sen)
62	    values (v_pay.org_id, v_pay.lease_id, v_pay.id, v_inv.id, v_take);
63	    v_remaining := v_remaining - v_take;
64	  end loop;
65	
66	  -- R26: leftover after every invoice is full stays on the payment. Manual payments are capped,
67	  -- so for them this is 0 and the row is not touched (keeps the D12 status trigger out of it).
68	  if v_remaining <> v_pay.unapplied_sen then
69	    update public.payments p
70	       set unapplied_sen = v_remaining
71	     where p.id = p_payment_id;
72	  end if;
73	end;
74	$$;
