1	import { badRequest, toErrorResponse } from '@/lib/errors'
2	
3	// Wraps a route handler so every thrown error becomes the SPEC error body (D2), never a stack trace.
4	export function route<C>(handler: (req: Request, ctx: C) => Promise<Response>): (req: Request, ctx: C) => Promise<Response> {
5	  return async (req, ctx) => {
6	    try {
7	      return await handler(req, ctx)
8	    } catch (e) {
9	      return toErrorResponse(e)
10	    }
11	  }
12	}
13	
14	export function json(body: unknown, status = 200): Response {
15	  return Response.json(body, { status })
16	}
17	
18	// R45: request bodies are JSON objects; anything else is a 400 before validation.
19	export async function readJson(req: Request): Promise<Record<string, unknown>> {
20	  let text: string
21	  try {
22	    text = await req.text()
23	  } catch {
24	    throw badRequest('Could not read the request body')
25	  }
26	  let parsed: unknown
27	  try {
28	    parsed = JSON.parse(text)
29	  } catch {
30	    throw badRequest('Malformed JSON body')
31	  }
32	  if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) {
33	    throw badRequest('Request body must be a JSON object')
34	  }
35	  return parsed as Record<string, unknown>
36	}
